-- CA General Election, 2026-11-03
on conflict (state_code, slug) do update set name = excluded.name,
  election_date = excluded.election_date, type = excluded.type;

select e.id, v.slug, v.office, v.district, v.level, v.partisan, v.sort_order
from public.elections e cross join (values
  ('governor', 'Governor', null::integer, 'statewide', true, 1),
  ('lieutenant-governor', 'Lieutenant Governor', null::integer, 'statewide', true, 2),
  ('attorney-general', 'Attorney General', null::integer, 'statewide', true, 3),
  ('secretary-of-state', 'Secretary of State', null::integer, 'statewide', true, 4),
  ('treasurer', 'Treasurer', null::integer, 'statewide', true, 5),
  ('controller', 'Controller', null::integer, 'statewide', true, 6),
  ('insurance-commissioner', 'Insurance Commissioner', null::integer, 'statewide', true, 7),
  ('superintendent-of-public-instruction', 'Superintendent of Public Instruction', null::integer, 'statewide', false, 8),
  ('board-of-equalization-1', 'Board of Equalization', 1::integer, 'statewide', true, 9),
  ('board-of-equalization-2', 'Board of Equalization', 2::integer, 'statewide', true, 10),
  ('board-of-equalization-3', 'Board of Equalization', 3::integer, 'statewide', true, 11),
  ('board-of-equalization-4', 'Board of Equalization', 4::integer, 'statewide', true, 12)
) as v (slug, office, district, level, partisan, sort_order)
where e.state_code = 'CA' and e.slug = '2026-11-03-general'
on conflict (election_id, slug) do update set office = excluded.office,
  district = excluded.district, level = excluded.level,
  partisan = excluded.partisan, sort_order = excluded.sort_order;

